import random


def brute(genres, k):
    best = 0
    n = len(genres)
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(genres[j])
            if len(seen) > k:
                break
            best = max(best, j - i + 1)
    return best


